import React, { useState, useEffect } from 'react';
import { CSSTransition, TransitionGroup } from 'react-transition-group';
import styled from 'styled-components';
import { navDelay, loaderDelay } from '@utils';
import { email } from '@config';
import { usePrefersReducedMotion } from '@hooks';

const StyledHeroSection = styled.section`
  ${({ theme }) => theme.mixins.flexCenter};
  flex-direction: column;
  align-items: flex-start;
  min-height: 100vh;
  height: 100vh;
  padding: 0;

  @media (max-height: 700px) and (min-width: 700px), (max-width: 360px) {
    height: auto;
    padding-top: var(--nav-height);
  }

  h1 {
    margin: 0 0 30px 4px;
    color: var(--green);
    font-family: var(--font-mono);
    font-size: clamp(var(--fz-sm), 5vw, var(--fz-md));
    font-weight: 400;

    @media (max-width: 480px) {
      margin: 0 0 20px 2px;
    }
  }

  h3 {
    margin-top: 5px;
    color: var(--slate);
    line-height: 0.9;
  }

  p {
    margin: 20px 0 0;
    max-width: 540px;
  }

  .highlight {
    color: var(--green);
  }

  .email-link {
    ${({ theme }) => theme.mixins.bigButton};
    margin-top: 50px;
  }
`;

const Hero = () => {
  const [isMounted, setIsMounted] = useState(false);
  const prefersReducedMotion = usePrefersReducedMotion();

  useEffect(() => {
    if (prefersReducedMotion) {
      return;
    }

    const timeout = setTimeout(() => setIsMounted(true), navDelay);
    return () => clearTimeout(timeout);
  }, []);

  const one = <h1>Namaste! I'm</h1>;
  const two = <h2 className="big-heading">Keshav Jha</h2>;
  const three = <h3 className="medium-heading">I break things before your users do.</h3>;
  const four = (
    <>
      <p>
        I am a <span className="highlight">SDET</span> with experience designing and implementing robust automation solutions 
        across web, mobile, API, and database layers. I specialize in building scalable 
        and maintainable test frameworks using {' '}
        <a href="https://playwright.dev/">Playwright</a>, {' '}
        <a href="https://selenium.dev/">Selenium</a> and {' '}
        <a href="https://appium.io/">Appium</a>.
      </p>

      <p>
        My focus is on combining strong automation practices with functional testing expertise and 
        comprehensive API automation to deliver reliable, high-quality software and confidence 
        throughout the software development lifecycle.
      </p>

      <p>
        Currently working as a Senior QA Engineer at{' '}
        <a href="https://www.ggwp.com/" target="_blank" rel="noreferrer">
          GGWP
        </a>
        .
      </p>
    </>
  );
  const five = (
    <a className="email-link" href={`mailto:${email}`}>
      Contact Me
    </a>
  );

  const items = [one, two, three, four, five];
  return (
    <StyledHeroSection>
      {prefersReducedMotion ? (
        <>
          {items.map((item, i) => (
            <div key={i}>{item}</div>
          ))}
        </>
      ) : (
        <TransitionGroup component={null}>
          {isMounted &&
            items.map((item, i) => (
              <CSSTransition key={i} classNames="fadeup" timeout={loaderDelay}>
                <div style={{ transitionDelay: `${i + 1}00ms` }}>{item}</div>
              </CSSTransition>
            ))}
        </TransitionGroup>
      )}
    </StyledHeroSection>
  );
};

export default Hero;
